```json
{
  "question": "Given a list of integers `nums`, find the length of the longest contiguous subsegment of numbers that can be rearranged to form a contiguous sequence of integers (i.e., the difference between the maximum and minimum elements in the subsegment equals the length of the subsegment minus one, and all elements in the subsegment are distinct). Return this maximum length.",
  "function_name": "longest_consecutive_subsegment",
  "signature": "def longest_consecutive_subsegment(nums: list[int]) -> int",
  "checker": "exact",
  "reference_solution": "def longest_consecutive_subsegment(nums: list[int]) -> int:\n    if not nums:\n        return 0\n    max_len = 0\n    n = len(nums)\n    for i in range(n):\n        min_val = nums[i]\n        max_val = nums[i]\n        seen = set()\n        for j in range(i, n):\n            if nums[j] in seen:\n                break\n            seen.add(nums[j])\n            min_val = min(min_val, nums[j])\n            max_val = max(max_val, nums[j])\n            if max_val - min_val == j - i:\n                max_len = max(max_len, j - i + 1)\n    return max_len",
  "cases": [
    {
      "args_json": "[[4, 2, 3, 1, 4]]",
      "expected_json": "4",
      "note": "Subsegment [2, 3, 1, 4] has min 1, max 4, length 4, and all elements distinct."
    },
    {
      "args_json": "[[5, 2, 6, 1, 4, 3]]",
      "expected_json": "6",
      "note": "All elements can form a single consecutive sequence from 1 to 6."
    },
    {
      "args_json": "[[]]",
      "expected_json": "0",
      "note": "Empty input returns 0."
    },
    {
      "args_json": "[[10]]",
      "expected_json": "1",
      "note": "Single element input."
    },
    {
      "args_json": "[[1, 2, 2, 1]]",
      "expected_json": "2",
      "note": "Duplicates prevent larger subsegments from being valid; longest valid is [1, 2] or [2, 1]."
    },
    {
      "args_json": "[[100, 4, 200, 1, 3, 2]]",
      "expected_json": "4",
      "note": "Subsegment [4, 1, 3, 2] can be rearranged to [1, 2, 3, 4]."
    }
  ]
}
```
